def page(file,title,desc,body,active='',scripts=''):
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==label else '')+f'>{label}</a>' for label,url in [('Projets','index.html#projets'),('Parcours','parcours.html'),('Air France','air-france.html'),('Compétences','competences.html')])
 html=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#091420"><title>{escape(title)} — Florian Marchois</title><meta name="description" content="{escape(desc)}"><meta property="og:title" content="{escape(title)} — Florian Marchois"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><link rel="icon" href="{ICON}"><link rel="stylesheet" href="assets/style.css"><script src="assets/site.js" defer></script>{scripts}</head><body><a class="skip" href="#main">Aller au contenu</a><div class="reading-progress" aria-hidden="true"></div><header class="header"><a class="brand" href="index.html" aria-label="Florian Marchois, accueil">fm<span>Florian Marchois</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span>＋</span></button><nav id="navigation" aria-label="Navigation principale">{nav}<a class="nav-contact" href="contact.html" {'aria-current="page"' if active=='Contact' else ''}>Échangeons ↗</a></nav></header><main id="main">{body}</main><footer><a href="index.html">Florian Marchois <span class="footer-sub">Élève ingénieur · Arts et Métiers</span></a><div><a href="contact.html">Contact</a><a href="{LINKEDIN}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="assets/florian-marchois-cv.pdf" download>CV ↓</a></div><span class="copyright">© 2026</span></footer></body></html>'''
 html=html.replace('<script src="assets/site.js"', '<link rel="stylesheet" href="assets/pages.css"><script src="assets/site.js"')
 for material in ['aluminium','bois']:
  html=html.replace(f'src="assets/mode-{material}.gif"',f'src="assets/mode-{material}.jpg" data-animation="assets/mode-{material}.gif" data-still="assets/mode-{material}.jpg"')
