cosa=hero('01','MÉCANIQUE & SIMULATION','De la matière<br><em>à la note juste.</em>','Le Compositeauphone : concevoir, fabriquer et accorder une lame de xylophone en matériaux composites.','<span>Arts et Métiers · 2A · 2025–2026</span><span>Projet collectif · 4 étudiants</span>')
cosa+='<div class="wrap">'+stats([('1 024','empilements étudiés par le modèle Python'),('20','plis dans le stratifié étudié'),('1 322,9 Hz','fréquence finale mesurée au microphone')])+'</div>'
cosa+='<nav class="chapter-nav wrap" aria-label="Dans ce projet"><a href="#enjeu">L’enjeu</a><a href="#approche">La démarche</a><a href="#experience">Écouter & explorer</a><a href="#resultats">Les résultats</a></nav>'
cosa+=section('enjeu','01 / LE DÉFI','Une lame doit<br>sonner juste.','<p class="large-copy">Changer de matériau transforme la vibration. Comment obtenir la note voulue avec une lame composite, alors que l’orientation des fibres et la fabrication influencent sa rigidité ?</p><p>Nous sommes partis des lames en bois et en aluminium pour relier géométrie, matériaux et fréquences propres. Puis nous avons transféré cette démarche à un stratifié composite, jusqu’à la fabrication et à la mesure de la pièce.</p>'+tags('Analyse modale','Éléments finis','Matériaux composites','Travail en équipe'))
cosa+=section('approche','02 / LA DÉMARCHE','Calculer vite.<br>Vérifier au réel.','''<div class="steps"><article><span>01</span><div><h3>Comprendre la vibration</h3><p>Modèles de poutre, amortissement et synthèse sonore sous Python. Les essais permettent d’identifier les modes de flexion et de torsion.</p></div></article><article><span>02</span><div><h3>Explorer les empilements</h3><p>Un modèle analytique couplé à la théorie des stratifiés explore 1 024 configurations symétriques à 20 plis. Abaqus sert ensuite à vérifier les configurations retenues.</p></div></article><article><span>03</span><div><h3>Fabriquer et contrôler</h3><p>Drapage, mise sous vide, cuisson et découpe. Un contrôle ultrasonore examine la qualité du stratifié avant la caractérisation vibratoire.</p></div></article><article><span>04</span><div><h3>Corriger la pièce</h3><p>La première fréquence mesurée est trop basse. Le retrait de matière aux extrémités permet de remonter la fréquence, avec un dimensionnement numérique puis une nouvelle mesure.</p></div></article></div>''')
cosa+='''<section class="section gallery-section"><div class="photo-pair"><figure><img src="assets/fabrication.jpg" alt="Moule contenant les plis du composite" width="600" height="800" loading="lazy"><figcaption>01 — Drapage dans le moule.</figcaption></figure><figure><img src="assets/mise-sous-vide.jpg" alt="Moule sous une poche à vide" width="600" height="800" loading="lazy"><figcaption>02 — Mise sous vide du stratifié.</figcaption></figure><figure><img src="assets/lame-usinee.jpg" alt="Lame composite avec évidements d’accordage aux deux extrémités" width="600" height="800" loading="lazy"><figcaption>03 — La lame après usinage d’accordage.</figcaption></figure></div>'''+note('Photographies extraites du rapport collectif COSA, pages 29 et 41.')+'</section>'
cosa+=section('experience','03 / EXPLORER','Un matériau.<br>Un autre timbre.','''<p>Ces gammes sont des sons de synthèse issus du projet. Elles rendent audible l’effet du modèle de lame et de son amortissement. Ce ne sont pas des enregistrements du prototype composite.</p><div class="audio-grid"><div class="audio-card"><h3>Aluminium</h3><img src="assets/mode-aluminium.gif" alt="Animation de la déformation d’une lame métallique" width="640" height="480" loading="lazy"><audio controls preload="none" src="assets/gamme-aluminium.wav" aria-label="Écouter la gamme synthétique aluminium"></audio></div><div class="audio-card"><h3>Bois</h3><img src="assets/mode-bois.gif" alt="Animation de la déformation d’une lame en bois" width="640" height="480" loading="lazy"><audio controls preload="none" src="assets/gamme-bois.wav" aria-label="Écouter la gamme synthétique bois"></audio></div></div><div class="engineering-note"><h3>Le compromis du modèle</h3><p>Le modèle analytique accélère l’exploration. Certaines orientations de fibres et les modes supérieurs exigent cependant une modélisation plus complète. L’intérêt est de savoir quand passer du calcul rapide aux éléments finis.</p></div>''')
cosa+=section('resultats','04 / DU CALCUL À LA MESURE','Accorder.<br>Puis mesurer.','''<div class="tuning-chart" role="img" aria-label="Avant accordage : 1226 hertz. Cible : 1318,5 hertz. Après accordage, mesure au microphone : 1322,9 hertz."><div><span>Avant accordage</span><b>1 226 Hz</b><i style="--bar:54%"></i></div><div><span>Cible Mi6 du projet</span><b>1 318,5 Hz</b><i style="--bar:96%"></i></div><div class="highlight"><span>Après accordage · microphone</span><b>1 322,9 Hz</b><i style="--bar:98%"></i></div><small>Échelle comparative : 1 100–1 330 Hz.</small></div><p>La mesure finale au microphone se situe à environ <strong>5,7 cents</strong> de la cible, soit un écart de fréquence de 0,33 %. Une mesure par accéléromètre donne une valeur légèrement plus basse : la masse du capteur influence elle-même la vibration.</p><details><summary>Voir la mesure expérimentale</summary><figure class="document-figure"><img src="assets/mesure-finale.jpg" alt="Spectre expérimental du microphone et pic de fréquence de la lame" loading="lazy"><figcaption>Extrait du rapport COSA, page 43.</figcaption></figure></details>'''+note('Résultats collectifs du rapport COSA, pages 42–44. La note « Mi6 » reprend la convention utilisée dans le projet.'))
cosa+=section('recul','05 / CE QUE J’EN RETIENS','Le modèle guide.<br>L’essai tranche.','<p class="large-copy">Une bonne prédiction ne suffit pas : la fabrication et la mesure ont leurs propres effets.</p><p>Ce projet relie programmation, mécanique, choix de matériaux et expérimentation. Il montre aussi pourquoi il faut garder une marge pour le recalage : épaisseur réelle, hétérogénéité du stratifié et conditions de mesure peuvent déplacer la fréquence.</p><p class="contribution">J’ai participé à ce projet avec trois autres étudiants. Les méthodes et résultats présentés sont ceux de notre travail collectif.</p>'+tags('Python','Abaqus','Analyse vibratoire','Confrontation modèle / expérience'))
cosa+=next_project('chanel.html','Chanel','Passer du comportement d’une lame à celui d’un réseau de distribution.')
page('compositeauphone.html','Compositeauphone','Conception et accordage d’une lame composite : Python, Abaqus, fabrication et analyse vibratoire expérimentale.',cosa,'Projets')

chanel=hero('02','SUPPLY CHAIN','Le bon stock.<br><em>Au bon endroit.</em>','Étudier l’organisation des stocks et les tailles de lots de produits de maquillage Chanel, de la production aux boutiques.','<span>Arts et Métiers · Projet académique collectif</span><span>Stocks · Flux · Distribution</span>')
chanel+=section('enjeu','01 / LE PROBLÈME','Relier production<br>et demande.','<p class="large-copy">Réduire les surstocks tout en gardant les produits disponibles : la question engage toute la chaîne de distribution.</p><p>Le projet étudie ensemble les tailles de lots, les stocks en boutique et la remontée d’information vers la production. La segmentation des produits conduit à proposer des réponses différentes selon leur profil.</p>'+tags('Gestion des stocks','Tailles de lots','Segmentation ABC','Analyse de scénarios'))
chanel+='''<section class="section wide-panel"><div class="panel-heading"><p class="eyebrow">EXPLORER LA LOGIQUE DES FLUX</p><h2>Où se situe le stock ?</h2><p>Deux organisations schématiques pour comprendre les pistes du projet.</p></div><div class="segmented" role="group" aria-label="Organisation des flux"><button data-flow="initial" aria-pressed="true">Organisation étudiée</button><button data-flow="proposed" aria-pressed="false">Piste proposée</button></div><div class="flow-diagram" id="flow-diagram"><div class="flow-node"><span>01</span><strong>Production</strong><small>Usine en France</small></div><div class="flow-line" aria-hidden="true">→</div><div class="flow-node middle-node"><span>02</span><strong id="flow-middle">Entrepôt central</strong><small id="flow-mid-caption">Distribution vers les boutiques</small></div><div class="flow-line" aria-hidden="true">→</div><div class="flow-node"><span>03</span><strong>Boutiques</strong><small id="flow-last-caption">Stock local important</small></div></div><p id="flow-description" class="flow-description" aria-live="polite">Dans l’organisation étudiée, le stock est réparti dans les boutiques. Le projet questionne sa localisation et la manière de déclencher les réapprovisionnements.</p>'''+note('Schéma explicatif redessiné à partir de la présentation Chanel. Il représente une logique de distribution, pas une simulation chiffrée.')+'</section>'
chanel+=section('approche','02 / LES PISTES','Adapter la réponse<br>au produit.','''<div class="decision-list"><article><span>C</span><div><h3>Mutualiser et mieux informer</h3><p>La piste étudiée consiste à utiliser des entrepôts relais et à faire remonter les besoins pour déclencher le réapprovisionnement. Le but est de limiter l’accumulation dans chaque boutique.</p></div></article><article><span>B</span><div><h3>Rapprocher les flux du marché</h3><p>Pour un autre segment, l’équipe explore une organisation par hubs régionaux et compare ses implications logistiques et économiques.</p></div></article><article><span>↔</span><div><h3>Revenir à la production</h3><p>Le travail inclut des pistes sur l’organisation des lignes et les tailles de lots. La distribution ne peut être optimisée indépendamment de l’atelier.</p></div></article></div>''')
chanel+=section('resultats','03 / LE LIVRABLE','Des scénarios<br>pour décider.','<p>Une présentation structurée rassemble le diagnostic, les schémas de flux avant/après et les recommandations. Elle inclut également une démonstration numérique pour rendre la proposition plus lisible.</p><p class="engineering-note">Les solutions sont des propositions issues du projet académique. Elles ne sont pas présentées comme un déploiement réalisé chez Chanel, ni comme des gains effectivement mesurés.</p>'+tags('Diagnostic','Comparaison d’organisations','Restitution visuelle','Recommandations'))
chanel+=section('recul','04 / CE QUE J’EN RETIENS','Regarder<br>toute la chaîne.','<p class="large-copy">Une décision sur la taille d’un lot déplace aussi des stocks, des délais et des besoins d’information.</p><p>Ce travail m’a amené à relier plusieurs niveaux de décision et à expliciter les hypothèses d’un scénario. L’enjeu est de proposer une organisation compréhensible, dont les effets peuvent ensuite être évalués.</p><p class="contribution">Participation à un travail collectif aux Arts et Métiers. Synthèse fondée sur la présentation du projet.</p>')
chanel+=next_project('boscha.html','Boscha','Analyser les capacités et les flux à l’échelle de l’atelier.')
page('chanel.html','Chanel · Stocks & Supply Chain','Projet académique Chanel : stocks, tailles de lots et comparaison de scénarios de distribution.',chanel,'Projets')

boscha=hero('03','PERFORMANCE INDUSTRIELLE','Comprendre les retards.<br><em>Repenser l’atelier.</em>','Boscha : une étude de cas qui relie charge des machines, circulation des pièces et choix d’investissement.','<span>Arts et Métiers · OREXA</span><span>Étude de cas collective · Organisation de production</span>')
boscha+=section('enjeu','01 / LE DIAGNOSTIC','La capacité globale<br>ne dit pas tout.','<p class="large-copy">Un atelier peut disposer de ressources tout en accumulant des retards sur un poste critique.</p><p>Le cas Boscha porte sur une gamme d’injecteurs. Nous avons étudié les gammes de fabrication, la charge des postes et les règles de lancement pour comprendre ce qui limite réellement le débit.</p>'+tags('Charge / capacité','Goulots','Gammes de fabrication','Gestion des flux'))
boscha+=section('methode','02 / LA MÉTHODE','Du poste machine<br>au plan d’atelier.','''<div class="steps"><article><span>01</span><div><h3>Comparer charge et capacité</h3><p>Ramener les besoins et les ressources au même horizon pour identifier les postes saturés et les marges disponibles.</p></div></article><article><span>02</span><div><h3>Cartographier les déplacements</h3><p>Construire une matrice de flux entre les opérations, les stockages et les étapes de sous-traitance.</p></div></article><article><span>03</span><div><h3>Adapter l’implantation</h3><p>Utiliser une proposition algorithmique comme point de départ, puis la retravailler pour intégrer les circulations et la forme réelle des postes.</p></div></article></div>''')
boscha+='''<section class="section layout-section"><div class="section-heading"><p class="eyebrow">LE PASSAGE AU CONCRET</p><h2>Un plan doit aussi<br>laisser passer les personnes.</h2><p>L’implantation proposée intègre des zones de circulation entre les postes.</p></div><figure class="document-figure"><img src="assets/implantation-boscha.jpg" alt="Plan d’implantation de l’atelier Boscha, avec postes colorés et voies de circulation" width="1280" height="720" loading="lazy"><figcaption>Extrait du support collectif COSYP — implantation avec circulations.</figcaption></figure></section>'''
boscha+=section('scenarios','03 / ARBITRER','Trois leviers.<br>Des compromis.','''<div class="scenario-cards"><article><span class="eyebrow">SCÉNARIO A</span><h3>Étendre les horaires</h3><p>Ajouter de la capacité par une équipe de fin de semaine.</p><span class="tradeoff">À examiner : coûts récurrents et contrainte sociale.</span></article><article><span class="eyebrow">SCÉNARIO B</span><h3>Ajouter une machine</h3><p>Renforcer le poste identifié comme goulot.</p><span class="tradeoff">À examiner : investissement et déplacement du goulot.</span></article><article><span class="eyebrow">SCÉNARIO C</span><h3>Développer la polyvalence</h3><p>Redistribuer la charge entre plusieurs équipements.</p><span class="tradeoff">À examiner : faisabilité des gammes et formation.</span></article></div><p>La comparaison croise effets capacitaires, coûts et contraintes d’organisation. Elle débouche sur une recommandation progressive, plutôt que sur un achat de machine considéré isolément.</p>'''+note('Options étudiées dans le rapport Boscha. Les effets attendus sont des résultats d’étude, pas des gains d’usine constatés.'))
boscha+=section('recul','04 / CE QUE J’EN RETIENS','Optimiser avec<br>les contraintes réelles.','<p class="large-copy">Une implantation mathématiquement intéressante peut devenir inutilisable si elle oublie les accès et les circulations.</p><p>Ce projet met en regard le modèle et l’usage concret de l’atelier. Il m’a appris à examiner une solution à plusieurs échelles : le poste, le flux complet, puis les moyens nécessaires à sa mise en œuvre.</p><p class="contribution">Étude collective. Présentation des méthodes et arbitrages documentés dans les livrables OREXA.</p>')
boscha+=next_project('data.html','Data & qualité','Utiliser les mesures de production pour comprendre la variabilité.')
page('boscha.html','Boscha · Organisation industrielle','Diagnostic capacitaire, matrice des flux et implantation d’atelier dans le cas Boscha.',boscha,'Projets')

data=hero('04','DATA & QUALITÉ','Des mesures.<br><em>Des décisions mieux ciblées.</em>','Modélisation statistique de bobines toriques : expliquer la variabilité de l’inductance et identifier les paramètres de fabrication à surveiller.','<span>Arts et Métiers · MINA · 2025–2026</span><span>Projet collectif · 3 étudiants</span>')
data+='<div class="wrap">'+stats([('199','bobines dans le jeu de données du projet'),('6','variables explicatives étudiées'),('2','approches confrontées : statistiques et physique')])+'</div>'
data+=section('probleme','01 / LA QUESTION','Que faut-il<br>vraiment mesurer ?','<p class="large-copy">Toutes les dimensions d’un composant varient. Toutes n’expliquent pas autant la variation de sa performance.</p><p>À partir des mesures de bobines produites en série, nous avons cherché à prédire l’inductance, puis à hiérarchiser les paramètres influents. L’objectif est de concentrer le contrôle sur les grandeurs utiles.</p>'+tags('Analyse exploratoire','Tests statistiques','Régression multiple','Python & Excel'))
data+='''<section class="section wide-panel"><div class="panel-heading"><p class="eyebrow">EXPLORER LES DONNÉES DU PROJET</p><h2>Chaque point est une bobine.</h2><p>Changez la variable pour observer sa relation avec l’inductance mesurée.</p></div><div class="segmented" role="group" aria-label="Variable du graphique"><button data-variable="e" aria-pressed="true">Entrefer</button><button data-variable="s" aria-pressed="false">Section du tore</button><button data-variable="t" aria-pressed="false">Température</button></div><div class="scatter-wrap"><svg id="scatter" viewBox="0 0 850 420" role="img" aria-labelledby="scatter-title scatter-desc"><title id="scatter-title">Inductance en fonction de l’entrefer</title><desc id="scatter-desc">Nuage de points issu du tableur de projet MINA. Une tendance décroissante relie l’entrefer et l’inductance.</desc></svg></div><p id="chart-insight" class="flow-description" aria-live="polite">L’entrefer est l’un des paramètres influents identifiés dans le rapport. Le nuage montre une tendance, que la régression multiple permet d’étudier avec les autres variables.</p>'''+note('Mesures extraites du tableur collectif MINA. Le graphique est exploratoire : une relation visuelle ne démontre pas, à elle seule, une causalité.')+'</section>'
data+=section('approche','02 / LA DÉMARCHE','Du tableau brut<br>au modèle.','''<div class="steps"><article><span>01</span><div><h3>Préparer et examiner</h3><p>Nettoyage des données et analyse des distributions. Le script Python utilise pandas, NumPy et SciPy pour examiner les variables et tester leur normalité.</p></div></article><article><span>02</span><div><h3>Construire et réduire</h3><p>La régression multiple relie les variables mesurées à l’inductance. L’étude de leur influence permet de rechercher un modèle plus ciblé.</p></div></article><article><span>03</span><div><h3>Confronter à la physique</h3><p>Comparer les relations statistiques au modèle du circuit magnétique pour comprendre pourquoi certaines dimensions jouent un rôle majeur.</p></div></article></div>''')
data+=section('resultats','03 / LE RÉSULTAT','Orienter<br>le contrôle qualité.','<p class="large-copy">L’entrefer et la section du tore ressortent comme deux leviers majeurs dans l’analyse de l’inductance.</p><p>Le rapport propose de cibler leur variabilité plutôt que de multiplier les contrôles indifférenciés. C’est une recommandation issue du modèle : aucune réduction effectivement obtenue en production n’est revendiquée ici.</p><div class="engineering-note"><h3>Ce que le modèle ne prouve pas</h3><p>Un bon ajustement aux données étudiées ne garantit pas la même performance sur une nouvelle série. La validation sur d’autres données et la vérification des hypothèses restent nécessaires avant un usage industriel.</p></div>')
data+=section('recul','04 / CE QUE J’EN RETIENS','Les données<br>et le sens physique.','<p class="large-copy">Le calcul fait apparaître une relation. La compréhension du système aide à l’interpréter.</p><p>Ce projet prolonge mon parcours en physique par une approche statistique. Il montre comment utiliser la programmation pour examiner les données, puis traduire l’analyse en une décision de contrôle.</p><p class="contribution">Travail collectif avec deux autres étudiants. Les analyses et recommandations sont celles du rapport MINA.</p>')
data+=next_project('air-france.html','Air France','Découvrir une autre facette de mon parcours : le travail au sein des équipages.')
page('data.html','Data · Statistiques & qualité','Analyse statistique de bobines toriques : données, Python, régression et confrontation à la physique.',data,'Projets',scripts='<script src="assets/data.js" defer></script>')

